#include <cmath>
#include <vector>

std::vector<double> terminal_values(const Payoff& payoff, double s,
                                    double u, double d, int n) {
    std::vector<double> v(n + 1);
    for (int j = 0; j <= n; ++j)
        v[j] = payoff(s * std::pow(u, j) * std::pow(d, n - j));
    return v;
}

